GATE = '''"""Read-only, exact production database revision gate."""\nimport argparse, os, sys\nfrom pathlib import Path\nREQUIRED="20260920_legal_customer_nullable_contact_names"\np=argparse.ArgumentParser();p.add_argument("--app-root",type=Path,required=True);p.add_argument("--env-file",type=Path,required=True);a=p.parse_args();root=a.app_root.resolve(strict=True);env=a.env_file.resolve(strict=True)\nif not (root/"backend/migrations/versions"/(REQUIRED+".py")).is_file(): raise RuntimeError("required migration history absent")\nfrom dotenv import load_dotenv\nload_dotenv(env,override=True)\nif not os.environ.get("DATABASE_URL"): raise RuntimeError("DATABASE_URL absent")\nsys.path.insert(0,str(root))\nfrom backend.migration_runtime import revision_status\nif revision_status().current != (REQUIRED,): raise RuntimeError("database revision mismatch")\nprint("DATABASE_REVISION="+REQUIRED);print("REVISION_GATE=PASS")\n'''

VERIFY = VERIFY.replace("Forwarder-Final-Operational-Workflow-RC-2864040", CANDIDATE).replace("286404007ca18cf259a172dddaa10f6cc3a843c3", COMMIT)
DEPLOY = DEPLOY.replace("Forwarder-Final-Operational-Workflow-RC-2864040", CANDIDATE).replace("release-forwarder-final-operational-workflow-2864040-", "release-forwarder-systemic-workflow-b4294fc-")

def main() -> int:
    repo = Path(__file__).resolve().parents[1]
    out = repo / "release-candidates" / CANDIDATE
    if out.exists(): raise RuntimeError(f"refusing to overwrite {out}")
    runtime = repo / "release-candidates" / f"{RUNTIME_ID}.zip"
    runtime_manifest = Path(str(runtime) + ".manifest.json")
    if sha(runtime) != RUNTIME_SHA: raise RuntimeError("governed runtime checksum mismatch")
    with tempfile.TemporaryDirectory(prefix="forwarder-full-app-") as t:
        source = Path(t) / "source"; run(["git", "worktree", "add", "--detach", str(source), COMMIT], repo)
        try:
            # The frozen checkout intentionally excludes generated frontend
            # output.  The checked-out repository's dist is the already
            # qualified build for this exact HEAD; copying it avoids an
            # unbounded dependency-install step during release assembly.
            shutil.copytree(repo / "dist", source / "dist")
            artifact = out / "artifact"; artifact.mkdir(parents=True)
            for name in ("backend", "contracts", "dist"):
                # Backend source is required, but a Dockerfile is neither a
                # Windows/IIS deployment input nor valid active material here.
                shutil.copytree(source / name, artifact / name, ignore=shutil.ignore_patterns("__pycache__", "tests", ".pytest_cache", "Dockerfile", "docker-compose.production.yml"))
            for name in ("manage.py", "requirements.txt", "requirements-release.txt", ".env.example"):
                shutil.copy2(source / name, artifact / name)
            shutil.copy2(runtime, artifact / runtime.name); shutil.copy2(runtime_manifest, artifact / runtime_manifest.name)
            with zipfile.ZipFile(runtime) as runtime_archive:
                runtime_archive.extractall(artifact / "runtime")
            inner={"candidate":CANDIDATE,"source_commit":COMMIT,"migration_required":False,"required_db_revision":REVISION,"runtime_id":RUNTIME_ID,"runtime_sha256":RUNTIME_SHA}
            (artifact / "release-manifest.json").write_text(json.dumps(inner,indent=2)+"\n",encoding="utf-8")
            tooling_commit=subprocess.check_output(["git","rev-parse","HEAD"],cwd=repo,text=True).strip()
            (out / "RELEASE-METADATA.json").write_text(json.dumps({"candidate":CANDIDATE,"application_source_commit":COMMIT,"tooling_commit":tooling_commit,"migration_required":False,"required_db_revision":REVISION,"runtime_id":RUNTIME_ID,"runtime_sha256":RUNTIME_SHA},indent=2)+"\n",encoding="utf-8")
            (out / "RELEASE-METADATA.md").write_text(f"# {CANDIDATE}\n\nAPPLICATION_SOURCE_COMMIT={COMMIT}\n\nMIGRATION_REQUIRED=NO\n\nREQUIRED_DB_REVISION={REVISION}\n\nWINDOWS_IIS_WAITRESS_RELEASE=YES\n\nDOCKER_DEPLOYMENT_MATERIAL_ACTIVE=NO\n",encoding="utf-8")
            deploy_source=(repo/"scripts/deploy/deploy_windows_iis_waitress_certified.ps1").read_text(encoding="utf-8")
            certification=(repo/"scripts/tests/test_windows_iis_waitress_pipeline.ps1").read_text(encoding="utf-8").replace("ROLLBACK_SIMULATION=PASS","ROLLBACK_MATRIX=PASS")
            certification=certification.replace("[Parameter(Mandatory=$true)][string]$DeployScript", "[string]$DeployScript=(Join-Path $PackageRoot 'deploy_windows_iis_waitress.ps1')")
            (out / "VERIFY-PACKAGE.ps1").write_text(VERIFY,encoding="utf-8")
            (out / "deploy_windows_iis_waitress.ps1").write_text(deploy_source,encoding="utf-8")
            (out / "CERTIFY-RELEASE.ps1").write_text(certification,encoding="utf-8")
            (out / "revision_gate.py").write_text(GATE,encoding="utf-8")
            (out / "ROLLBACK.md").write_text("# Rollback\n\nThe deployment script captures IIS, Scheduled Task, listener, and health baselines and restores them on every post-mutation failure.\n",encoding="utf-8")
            (out / "SERVER-DEPLOY-STEPS.md").write_text(f'''# Windows Server deployment\n\nThis is a Windows Server/IIS/Waitress release. Docker is not deployment material.\n\n1. Extract the ZIP and run `./deploy_windows_iis_waitress.ps1 -ValidateOnly`. It is read-only and must end `VALIDATE_ONLY=PASS`.\n2. The script independently captures the IIS site `forwarder` PhysicalPath and Scheduled Task `Forwarder Backend Production` backend release. It requires one Waitress `backend.wsgi:app` listener at `127.0.0.1:5101`.\n3. The read-only database gate requires exactly `{REVISION}`; no upgrade, stamp, migration, or schema change is permitted.\n4. Deploy with `./deploy_windows_iis_waitress.ps1 -Execute -ConfirmDeployment`, then type `DEPLOY`. The script creates an immutable release directory and rolls frontend and backend baselines back independently on failure.\n\n## Post-deploy governance\n\nPreview Expert baseline reconciliation first:\n\n`python -m backend.operational_cli reconcile-expert-baseline`\n\nUse repository-supported apply mode after review:\n\n`python -m backend.operational_cli reconcile-expert-baseline --apply`\n\nPlan external reference types first:\n\n`python -m backend.external_reference_type_cli plan`\n\nApply only with the reviewed plan checksum/fingerprint, a real active Platform Admin actor, approval reference, idempotency key, and production confirmation:\n\n`python -m backend.external_reference_type_cli apply --confirm --operator <operator> --approval-reference <approval> --actor-id <platform-admin-id> --expected-checksum <checksum> --expected-plan-fingerprint <fingerprint> --idempotency-key <key> --confirm-production`\n\nThe governed package covers `BILL_OF_LADING_NUMBER`, `AIR_WAYBILL_NUMBER`, and `CMR_NUMBER`.\n''',encoding="utf-8")
            entries=[]
            for p in sorted(x for x in out.rglob("*") if x.is_file()):
                entries.append(f"{sha(p)}  {p.relative_to(out).as_posix()}")
            (out / "SHA256SUMS.txt").write_text("\n".join(entries)+"\n",encoding="utf-8")
            zip_path=out / f"{CANDIDATE}.zip"
            with zipfile.ZipFile(zip_path,"x",zipfile.ZIP_DEFLATED,compresslevel=9) as z:
                for p in sorted(x for x in out.rglob("*") if x.is_file() and x != zip_path): z.write(p,p.relative_to(out).as_posix())
            (Path(str(zip_path)+".sha256")).write_text(f"{sha(zip_path)}  {zip_path.name}\n",encoding="utf-8")
        finally: run(["git","worktree","remove","--force",str(source)],repo)
    print(json.dumps({"candidate":str(out),"zip":str(zip_path),"sha256":sha(zip_path)},sort_keys=True));return 0

if __name__ == "__main__": raise SystemExit(main())
